"""Calculate cleaning-service salaries by monthly Tuesday billing period."""

from __future__ import annotations

import csv
import json
import re
from collections import defaultdict
from datetime import date, timedelta
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path


DATASET = Path("/app/dataset")


def _rows(filename: str):
    with (DATASET / filename).open(newline="", encoding="utf-8") as file:
        yield from csv.DictReader(file)


def _first_weekday(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def _billing_month(work_date: date, weekday: int) -> tuple[int, int]:
    if work_date >= _first_weekday(work_date.year, work_date.month, weekday):
        return work_date.year, work_date.month
    if work_date.month == 1:
        return work_date.year - 1, 12
    return work_date.year, work_date.month - 1


def _month_range(first: tuple[int, int], last: tuple[int, int]):
    year, month = first
    while (year, month) <= last:
        yield year, month
        year, month = (year + 1, 1) if month == 12 else (year, month + 1)


def answer() -> dict[str, list[int]]:
    rates = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _rows("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _rows("tasks.csv")
    }

    # An id can differ between otherwise identical copies of the same shift.
    seen_shifts: set[tuple[str, ...]] = set()
    shifts: list[tuple[str, date, int, str]] = []
    for row in _rows("timesheet.csv"):
        pesel = row["employee_id"]
        if pesel not in rates:
            continue
        try:
            work_date = date.fromisoformat(row["date"])
            hours = int(row["hours_worked"])
        except ValueError:
            continue
        if not 0 <= hours <= 24:
            continue
        shift_key = tuple(value for key, value in row.items() if key != "id")
        if shift_key in seen_shifts:
            continue
        seen_shifts.add(shift_key)
        shifts.append((pesel, work_date, hours, row["performed_tasks"]))

    if not shifts:
        return {}

    weekday = min(work_date for _, work_date, _, _ in shifts).weekday()
    totals: dict[tuple[str, tuple[int, int]], Decimal] = defaultdict(Decimal)
    months: set[tuple[int, int]] = set()
    for pesel, work_date, hours, performed_tasks in shifts:
        month = _billing_month(work_date, weekday)
        months.add(month)
        # Numeric task IDs remain recoverable when a list bracket is damaged.
        bonus = sum(
            (task_pay.get(int(task_id), Decimal(0))
             for task_id in re.findall(r"\d+", performed_tasks)),
            Decimal(0),
        )
        totals[(pesel, month)] += rates[pesel] * hours + bonus

    billing_months = list(_month_range(min(months), max(months)))
    return {
        pesel: [
            int(totals[(pesel, month)].quantize(Decimal("1"), rounding=ROUND_HALF_UP))
            for month in billing_months
        ]
        for pesel in rates
    }


if __name__ == "__main__":
    with Path("/app/answer.json").open("w", encoding="utf-8") as file:
        json.dump(answer(), file)

